@RunWith(MockitoJUnitRunner.class)
public class BuildGlobalNamespace_collect_TriageGen1Test {

    private BuildGlobalNamespace.BuildGlobalNamespace buildGlobalNamespace;

    @Mock private JSModule mockModule;
    @Mock private Scope mockScope;
    @Mock private Node mockNode;
    @Mock private Node mockParent;
    @Mock private Node mockGrandparent;

    @Before
    public void setUp() {
        // We use a spy to bypass the complex internal logic of handleSet and handleGet 
        // which are likely to require heavy setup of the whole compiler state.
        buildGlobalNamespace = spy(new BuildGlobalNamespace.BuildGlobalNamespace());
    }

    private void setupNode(int type, String value) {
        when(mockNode.getType()).thenReturn(type);
        if (value != null) {
            when(mockNode.getString()).thenReturn(value);
        }
    }

    @Test
    public void testCollect_StringKey_ObjectLit_Success() {
        setupNode(Token.STRING_KEY, "key");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.isObjectLit()).thenReturn(true);
        when(mockNode.getFirstChild()).thenReturn(mock(Node.class)); // for getValueType

        // Mocking internal helper methods via spy
        doReturn("key").when(buildGlobalNamespace).getNameForObjLitKey(mockNode);
        doReturn(Name.Type.OTHER).when(buildGlobalNamespace).getValueType(any());
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("key"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("key"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_GetterDef_ObjectLit() {
        setupNode(Token.GETTER_DEF, null);
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.isObjectLit()).thenReturn(true);
        doReturn("getter").when(buildGlobalNamespace).getNameForObjLitKey(mockNode);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("getter"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("getter"), eq(false), eq(Name.Type.GET));
    }

    @Test
    public void testCollect_SetterDef_ObjectLit() {
        setupNode(Token.SETTER_DEF, null);
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.isObjectLit()).thenReturn(true);
        doReturn("setter").when(buildGlobalNamespace).getNameForObjLitKey(mockNode);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("setter"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("setter"), eq(false), eq(Name.Type.SET));
    }

    @Test
    public void testCollect_Name_Var_Declaration() {
        setupNode(Token.NAME, "varName");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.VAR);
        Node rvalue = mock(Node.class);
        when(mockNode.getFirstChild()).thenReturn(rvalue);
        doReturn(Name.Type.STRING).when(buildGlobalNamespace).getValueType(rvalue);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("varName"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("varName"), eq(false), eq(Name.Type.STRING));
    }

    @Test
    public void testCollect_Name_Assignment_LeftHandSide() {
        setupNode(Token.NAME, "x");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.ASSIGN);
        when(mockParent.getFirstChild()).thenReturn(mockNode);
        Node next = mock(Node.class);
        when(mockNode.getNext()).thenReturn(next);
        doReturn(Name.Type.NUMBER).when(buildGlobalNamespace).getValueType(next);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("x"), eq(false), eq(Name.Type.NUMBER));
    }

    @Test
    public void testCollect_Name_Function_Declaration() {
        setupNode(Token.NAME, "funcName");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.FUNCTION);
        when(mockParent.getParent()).thenReturn(mockGrandparent);
        // Not a function expression (e.g., a function declaration)
        // Assuming NodeUtil.isFunctionExpression(parent) returns false via mock/logic
        // We'll mock the logic by ensuring parent is not a function expression
        // Since we can't mock static NodeUtil easily without PowerMock, 
        // we assume the code path reaches isSet = true.

        // To trigger the 'return' inside Token.FUNCTION, parent must be a function expression.
        // To trigger 'isSet = true', parent must NOT be a function expression.
        // Let's simulate the non-expression path.
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("funcName"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        // Note: In real tests, you'd use a real Node structure or a specialized mock for NodeUtil.
        // Here we simulate the logic flow.
        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);
        // The behavior depends on NodeUtil.isFunctionExpression which is a static call.
    }

    @Test
    public void testCollect_Name_IncDec() {
        setupNode(Token.NAME, "i");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.INC);
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("i"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("i"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_GetProp_Assign() {
        setupNode(Token.GETPROP, null);
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.ASSIGN);
        when(mockParent.getFirstChild()).thenReturn(mockNode);
        when(mockNode.getNext()).thenReturn(mock(Node.class));
        when(mockNode.getQualifiedName()).thenReturn("a.b");
        doReturn(Name.Type.STRING).when(buildGlobalNamespace).getValueType(any());
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("a.b"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("a.b"), eq(true), eq(Name.Type.STRING));
    }

    @Test
    public void testCollect_GetProp_Inc() {
        setupNode(Token.GETPROP, null);
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.INC);
        when(mockNode.getQualifiedName()).thenReturn("a.b");
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("a.b"), eq(mockScope));
        doReturn(true).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromGlobal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("a.b"), eq(false), eq(Name.Type.OTHER));
    }

    @Test
    public void testCollect_Get_Global() {
        setupNode(Token.NAME, "globalVar");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.GETPROP); // parent is GETPROP, node is NAME -> triggers return
        // Actually, if parent is GETPROP, it returns immediately.

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_Name_Get_Global() {
        setupNode(Token.NAME, "x");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.ASSIGN); // Not a special parent for NAME
        // In the 'default' of parent switch:
        // if (NodeUtil.isAssignmentOp(parent) && parent.getFirstChild() == n)
        // Let's simulate that:
        // Since NodeUtil is static, we assume the logic for assignment op works.
        // Let's try a simpler case: NAME where isSet remains false.
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), eq(mockScope));

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleGet(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("x"));
    }

    @Test
    public void testCollect_NotGlobal() {
        setupNode(Token.NAME, "local");
        when(mockNode.getParent()).thenReturn(mockParent);
        doReturn(false).when(buildGlobalNamespace).isGlobalNameReference(eq("local"), eq(mockScope));

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
        verify(buildGlobalNamespace, never()).handleSetFromGlobal(any(), any(), any(), any(), any(), any(), any());
        verify(buildGlobalNamespace, never()).handleSetFromLocal(any(), any(), any(), any(), any());
    }

    @Test
    public void testCollect_LocalScope_Set() {
        setupNode(Token.NAME, "x");
        when(mockNode.getParent()).thenReturn(mockParent);
        when(mockParent.getType()).thenReturn(Token.VAR);
        when(mockNode.getFirstChild()).thenReturn(mock(Node.class));
        doReturn(true).when(buildGlobalNamespace).isGlobalNameReference(eq("x"), eq(mockScope));
        doReturn(false).when(buildGlobalNamespace).isGlobalScope(mockScope);

        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);

        verify(buildGlobalNamespace).handleSetFromLocal(eq(mockModule), eq(mockScope), eq(mockNode), eq(mockParent), eq("x"));
    }

    @Test
    public void testCollect_InvalidToken() {
        setupNode(Token.COMMA, null);
        buildGlobalNamespace.collect(mockModule, mockScope, mockNode);
        verify(buildGlobalNamespace, never()).handleGet(any(), any(), any(), any(), any());
    }
}
